with ins as (insert into public.artist_eras (artist_slug,from_year,to_year,sound,tags,source_url,source_name,palette) select x.s,x.f,x.t,x.snd,array(select json_array_elements_text(x.tags)),x.u,x.n,x.p from json_to_recordset('[{"s":"anish-sood","f":2021,"t":2024,"snd":"Classical Indian vocals over 303s and melodic house","tags":["melodic house","classical Indian vocals","303","progressive"],"u":"https://mixmag.net/read/anyasa-in-the-lab-goa-dj-lab","n":"Mixmag","p":"blush"},{"s":"anish-sood","f":2025,"t":null,"snd":"Melodic house and techno, moving toward English vocals","tags":["melodic house","techno","deep house","synths"],"u":"https://rollingstoneindia.com/anyasa-flectere-ep-north-america-tour","n":"Rolling Stone India","p":"ink"},{"s":"aayna","f":2025,"t":null,"snd":"Genre-bending acid sets driven by the TB-303","tags":["acid","TB-303","UKG","electronica","bass"],"u":"https://www.youtube.com/watch?v=eyS5yFogzFY","n":"New Delhi Community Radio (YouTube)","p":"night"},{"s":"rohan-rakhit","f":2024,"t":null,"snd":"House, broken beat and jazz, soulful and percussive","tags":["house","broken beat","jazz"],"u":"https://www.mixcloud.com/blog/2026/04/08/rohan-rakhit-my-spotlights","n":"Mixcloud Blog","p":"ink"},{"s":"lush-lata","f":2023,"t":null,"snd":"Hip-hop and bass built on Bollywood grooves","tags":["hip-hop","bass","Bollywood","trap"],"u":"https://www.thewildcity.com/mixes/20112-wild-city-222-lush-lata","n":"Wild City","p":"night"},{"s":"discokid","f":2022,"t":null,"snd":"Laid-back funk, glittery disco and sultry house","tags":["funk","disco","house"],"u":"https://grayarea.co/magazine/mixmag-lab-goa-discokid-mix-of-the-week","n":"Gray Area","p":"night"},{"s":"mc-soopy","f":2026,"t":null,"snd":"Genre-fluid DJ sets blending hip hop, house and amapiano","tags":["hip hop","house","amapiano","garage","techno"],"u":"https://www.youtube.com/watch?v=qaR0z0xGras","n":"New Delhi Community Radio (YouTube)","p":"ink"}]'::json) as x(s text,f int,t int,snd text,tags json,u text,n text,p text) join public.artists a on a.slug=x.s where not exists (select 1 from public.artist_eras e where e.artist_slug=x.s and e.from_year=x.f) returning 1) select count(*) from ins;